#include <errno.h>
#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    const char input[] = "  -245tail";
    char *end = NULL;
    long value;

    errno = 0;
    value = strtol(input, &end, 10);

    if (end == input) {
        puts("No digits were converted.");
        return EXIT_FAILURE;
    }
    if (errno == ERANGE) {
        puts("The converted value is outside the range of long.");
        return EXIT_FAILURE;
    }
    if (*end != '\0') {
        printf("Unconsumed suffix begins at: %s\n", end);
        return EXIT_FAILURE;
    }

    printf("Value: %ld\n", value);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>

static int compare_ints(const void *left, const void *right)
{
    const int a = *(const int *)left;
    const int b = *(const int *)right;

    return (a > b) - (a < b);
}

int main(void)
{
    int values[] = { 42, -7, 18, 0, 18 };
    const size_t count = sizeof values / sizeof values[0];
    size_t i;

    qsort(values, count, sizeof values[0], compare_ints);

    for (i = 0; i < count; ++i) {
        printf("%d%c", values[i], i + 1 == count ? '\n' : ' ');
    }
    return 0;
}
